from lib import *
recs=[
R(2230,"Air Infus Blackberry-Sage",
"Air adalah salah satu minuman paling sehat bagi pasien ginjal–tetapi tidak ada yang bilang harus polos dan hambar! Cobalah Air Infus Blackberry-Sage, salah satu dari banyak resep air infus dari ahli gizi DaVita, Kara.",
"10","1 cangkir (8 ons)",
["1 cangkir blackberry segar","4 daun sage","10 cangkir air"],
["Haluskan blackberry.","Masukkan semua bahan ke dalam teko.","Simpan di lemari es semalaman sebelum disajikan."],
["Jika Anda membatasi cairan, sesuaikan ukuran porsi dengan kebutuhan Anda.","Setelah rasa berkembang, Anda dapat menuangkannya ke cetakan es batu untuk membuat es berperisa."],
["tidak ada"]),
R(2232,"Smoothie Lemon",
"Smoothie Lemon adalah minuman menyegarkan bagi penderita diabetes yang menjalani dialisis. Resep ini menggunakan putih telur, yang dapat menjadi cara yang bagus untuk menggantikan protein lain dalam diet ginjal.",
"1","9 ons",
["2 sendok teh air lemon","4 sendok teh gula (atau pengganti gula)","8 ons putih telur cair pasteurisasi","3 sendok makan krim kocok"],
["Campurkan semua bahan.","Aduk hingga krim kocok mencair sepenuhnya."],
["Penderita diabetes dapat menggunakan stevia, Equal®, Splenda®, atau pengganti gula lainnya jika diinginkan. Karbohidrat berkurang menjadi 6 gram per porsi jika pengganti gula digunakan sebagai pengganti gula."],
["4 daging","1 berkalori tinggi"]),
R(2234,"Kue Jagung Panggang dengan Keju (Arepa)",
"Kue Jagung Panggang dengan Keju, juga dikenal sebagai Arepa, adalah makanan sehari-hari yang populer di Kolombia.",
"4","1 kue jagung",
["2/3 cangkir tepung jagung putih","4 ons keju costeño","1/2 sendok teh adas manis","1 cangkir air panas","1 sendok teh mentega"],
["Letakkan tepung jagung dalam mangkuk.","Parut keju dan tambahkan keju dan adas manis ke tepung.","Tambahkan air hangat; aduk dengan spatula.","Diamkan selama 10 menit lalu uleni selama 2 hingga 3 menit.","Untuk membentuk kue jagung, buat 4 lingkaran selebar sekitar 4 inci dan setebal 1/2 inci.","Olesi wajan atau cetakan arepa dengan mentega. Letakkan setiap kue jagung di wajan atau cetakan arepa dan masak hingga sedikit kecokelatan."],
["Arepa adalah makanan populer di Kolombia.","Tepung arepa sudah dimasak dan dikeringkan serta dibuat khusus untuk membuat arepa. Dapat dibeli secara online atau Anda dapat menggantinya dengan tepung jagung maza.","Keju costeño adalah keju keras yang asin. Anda dapat menggantinya dengan keju cotija atau Parmesan."],
["1 daging","2-1/2 makanan pokok bertepung","1 lemak"]),
R(2236,"Salad Mentimun Creamy",
"Nikmati kesegaran Salad Mentimun Creamy ini pada hari musim panas yang panas. Anda dapat menyantap salad ramah ginjal ini apa adanya, atau menambahkan bawang bombai dan kolantro untuk menambah cita rasa.",
"2","1/2 cangkir",
["1 mentimun sedang","1/3 cangkir krim asam","2 sendok makan cuka putih","1 sendok makan gula","1/8 sendok teh lada hitam","1 sendok makan dill segar"],
["Iris tipis mentimun.","Campurkan krim asam, cuka (atau air lemon), gula (atau pemanis), dan lada.","Campurkan dengan mentimun. Dinginkan sebelum disajikan.","Hiasi dengan dill segar cincang jika diinginkan."],
["Ganti cuka dengan air lemon jika lebih suka.","Untuk variasi tambahkan 2 sendok makan bawang bombai atau daun kucai cincang.","Untuk versi yang lebih ringan, gunakan krim asam bebas lemak sebagai pengganti krim asam biasa."],
["1 sayuran, kalium rendah","1 lemak"]),
R(2242,"Pai Merah, Putih dan Biru",
"Resep lezat dan ramah ginjal Pai Merah, Putih dan Biru ini patriotik, menyehatkan, dan sangat menyegarkan. Blueberry, topping kocok, dan raspberry atau stroberi menghadirkan palet warna dan rasa manis untuk hidangan favorit 4 Juli ini. Disukai banyak orang bahkan bagi mereka yang tidak menjalani diet dialisis—dan suguhan sehat bagi yang menjalaninya.",
"8","1/8 pai",
["8 ons krim keju kocok rendah lemak","1/2 cangkir preserves raspberry merah rendah gula","3 cangkir topping kocok susu Reddi-Wip®","1 kulit graham cracker siap pakai, ukuran 9″","1 cangkir blueberry segar","1-1/2 cangkir raspberry segar"],
["Untuk membuat isian, kocok krim keju kocok dan preserves hingga halus dengan mixer listrik pada kecepatan sedang.","Lipat topping kocok ke dalam campuran krim keju.","Ratakan isian di dasar kulit graham cracker.","Dinginkan setidaknya 30 menit di lemari es atau freezer.","Sebelum disajikan tata blueberry di sekeliling lingkaran luar pai. Susun raspberry di sekeliling lingkaran dalam pai.","Selesaikan dekorasi dengan sesendok topping kocok di tengah dan satu raspberry atau stroberi di atasnya."],
["Bagi sisa pai menjadi porsi tunggal, bungkus dan bekukan untuk dessert cepat nanti.","Untuk variasi buat pai dengan buah segar dan preserves yang berbeda. Cobalah stroberi, persik, nanas, atau jeruk mandarin."],
["1/2 makanan pokok bertepung","1/2 buah, kalium rendah","1 susu"]),
R(2246,"Lettuce Wrap Ayam",
"Satu wajan adalah semua yang Anda butuhkan untuk membuat Lettuce Wrap Ayam yang lezat dan ramah ginjal. Panaskan ayam dan campurkan rempah lezat, lalu nikmati semuanya terbungkus dalam daun selada yang dingin dan renyah.",
"4","2 wrap (1/2 cangkir campuran ayam, 2 daun selada)",
["8 ons dada ayam, matang","2 batang daun bawang","2 sendok teh bawang putih","2 sendok makan minyak canola","1 sendok makan minyak wijen","2 sendok makan cuka beras tanpa bumbu","2 sendok teh saus hoisin","1 sendok teh bumbu Chinese Five Spices","1/4 cangkir bawang merah","1/4 cangkir kolantro segar","1/4 cangkir jamur","8 daun selada"],
["Cincang halus dada ayam dan bawang putih. Cincang daun bawang, bawang bombai, kolantro, dan jamur.","Dalam wajan sedang campurkan ayam, daun bawang, bawang putih, minyak canola, minyak wijen, cuka beras, saus hoisin, dan bumbu Chinese Five Spices. Masak dengan api sedang-kecil selama 15 menit, aduk beberapa kali.","Pindahkan ayam ke mangkuk saji. Letakkan 1/4 cangkir ayam di setiap daun selada. Taburi dengan masing-masing 1-2 sendok teh bawang merah, jamur, paprika merah, dan kolantro atau peterseli. Bungkus daun selada di sekeliling campuran ayam dan angkat untuk dimakan."],
["Saus hoisin biasanya ditemukan di bagian makanan Cina atau Asia di sebagian besar toko bahan makanan. Salah satu merek, saus hoisin Sun Luck®, dapat ditemukan dengan mencari di Google.","Chinese five spices adalah kombinasi kayu manis bubuk, bunga lawang, adas, jahe, cengkih, lada putih, dan akar manis. Chinese Five Spices® merek Dynasty ditemukan di bagian rempah di sebagian besar toko bahan makanan. Alamat mereka adalah JFC International Inc., Five Spice Recipes, PO Box 7251, San Francisco, CA 94120."],
["2 daging","1 sayuran, kalium rendah","1 lemak"]),
R(2247,"Sirloin Sapi Nikaragua",
"Siap menambahkan “cha-cha-cha” ke masakan Anda? Bepergianlah ke selatan perbatasan bersama ahli gizi DaVita, Robin, untuk Sirloin Sapi Nikaragua yang ramah ginjal.",
"4","3 ons",
["1 pon daging has dalam sapi, lemak yang terlihat dibuang","1 sendok teh lada hitam bubuk","1/2 cangkir bawang bombai, diiris tipis","1/4 cangkir peterseli flat-leaf segar, dicincang","2 siung bawang putih, dicincang halus","2 lembar daun salam","3 sendok makan cuka anggur merah","1 bawang bombai manis besar, dipotong menjadi empat irisan setebal 1/2”","1/2 cangkir Saus Chimichurri"],
["Letakkan daging memanjang di talenan. Potong daging searah serat menjadi 4 irisan datar yang rata. Letakkan setiap irisan di antara 2 lembar plastik pembungkus dan pukul hingga setebal 1/4” dengan pemukul daging. Bumbui dengan lada bubuk dan tata dalam loyang 9” x 13”.","Dalam mangkuk, campurkan 1/2 cangkir bawang bombai iris tipis, peterseli, bawang putih, daun salam, dan cuka. Kocok hingga tercampur dan tuang di atas daging. Tutup daging dan marinasi selama 8 menit; balik daging dan marinasi 8 menit lagi.","Panaskan panggangan atau broiler. Lumuri irisan bawang bombai manis dengan semprotan masak dan panggang hingga kecokelatan sempurna, sekitar 4 menit per sisi. Letakkan irisan bawang bombai di piring saji.","Letakkan daging di panggangan atau broiler dan buang marinasenya. Panggang daging yang telah dimarinasi 2 menit per sisi untuk medium rare atau hingga suhu internal 150º F untuk medium. Tata irisan daging di atas bawang bombai panggang.","Sajikan dengan porsi 3 ons daging has matang dengan 2 sendok makan Saus Chimichurri."],
["Gunakan bawang bombai putih atau kuning yang lebih tajam untuk marinasi dan panggang irisan bawang bombai manis.","Untuk diet protein lebih rendah, sesuaikan porsi daging sesuai rencana makan dan resep protein Anda."],
["3 daging","1-1/2 sayuran, kalium sedang","1 lemak"]),
R(2251,"Pancake Power",
"Beth Ann dari Minnesota awalnya adalah seorang guru dan minatnya pada nutrisi membuatnya menjadi ahli gizi ginjal. Pelajari semua tentang Beth Ann dan resepnya Pancake Power—cara kaya protein untuk memulai hari Anda.",
"2","satu pancake 6\"",
["1/2 cangkir cottage cheese","2 butir telur","1/2 cangkir tepung terigu serbaguna"],
["Siapkan wajan datar atau wajan dengan semprotan masak antilengket dan panaskan.","Campurkan semua bahan dalam blender atau food processor hingga halus.","Tuang adonan ke wajan yang telah disiapkan untuk membuat dua pancake 6″. Masak kedua sisinya.","Sajikan polos atau dengan topping buah, preserves, atau sirup."],
["Analisis tidak mencakup topping yang disarankan.","Buat pancake sandwich gurih dengan menambahkan 2 sendok teh bumbu Italia kering atau rempah lain pilihan Anda ke dalam adonan sebelum dimasak. Setelah matang, taburi dengan daging dan isian sandwich."],
["2 daging","1-1/2 makanan pokok bertepung"]),
R(2253,"Smoothie Buah",
"Nikmati cita rasa buah campur bersama bubuk protein rasa vanila dalam smoothie favorit Tahseen. Tahseen adalah ahli gizi ginjal DaVita dari Florida yang membagikan resep Smoothie Buah yang lezat dan ramah ginjal, minuman protein yang sempurna.",
"2","1-1/2 cangkir",
["8 ons fruit cocktail kaleng, dengan jusnya","2 sendok takar bubuk protein whey rasa vanila","1 cangkir air dingin","1 cangkir es serut"],
["Campurkan semua bahan dalam blender.","Bagi menjadi 2 porsi dan sajikan."],
["Resep ini menggunakan fruit cocktail kaleng dalam jus. Untuk smoothie berkalori lebih tinggi gunakan fruit cocktail dalam sirup ringan atau kental. Untuk kalori lebih rendah gunakan buah kaleng dalam air atau dengan pemanis buatan.","Simpan atau bekukan porsi ekstra untuk nanti.","Tanyakan kepada ahli gizi Anda tentang protein whey terbaik yang digunakan. Produk bervariasi dalam kandungan kalsium, kalium, dan fosfor."],
["3 daging","1 buah, kalium rendah"]),
R(2256,"Nasi Jollof dengan Ayam",
"Siap mencoba menjadi gourmet dunia? Maka berlayarlah menyusuri Kongo bersama ahli gizi DaVita, Victoria, dan resepnya yang menggugah selera dan ramah ginjal, Nasi Jollof dengan Ayam.",
"9","1-1/2 cangkir",
["1 pon dada ayam tanpa tulang dan tanpa kulit","1 sendok teh bumbu herba Mrs. Dash","3/4 cangkir wortel","3/4 cangkir buncis","3/4 cangkir paprika","3/4 cangkir kembang kol","2 sendok makan minyak","4 cangkir kaldu ayam rendah natrium","1 cangkir bawang bombai","4 siung bawang putih","2 cabai jalapeno","1/2 cangkir tomat hancur kaleng","2 sendok makan pasta tomat","1 pon beras butir panjang, mentah","peterseli atau kolantro untuk hiasan"],
["Potong ayam menjadi dadu kecil dan bumbui dengan bumbu Mrs. Dash®.","Cincang wortel, buncis, paprika, dan kembang kol. Cincang halus bawang putih dan cabai jalapeno.","Campurkan wortel, buncis, paprika, dan kembang kol cincang dalam mangkuk. Bagi menjadi dua.","Panaskan minyak dalam wajan dengan api sedang-tinggi. Masukkan potongan ayam dan goreng hingga cokelat keemasan.","Pindahkan ayam ke panci besar. Tambahkan 3 cangkir kaldu ayam dan didihkan. Kecilkan api dan masak perlahan hingga ayam mulai melunak.","Masukkan bawang bombai, bawang putih, dan cabai jalapeno ke dalam wajan yang digunakan untuk menggoreng ayam. Tumis hingga empuk. Tambahkan tomat, pasta tomat, setengah sayuran cincang, dan 1 cangkir kaldu ayam yang disisihkan. Didihkan perlahan 5 hingga 7 menit, sering diaduk.","Tambahkan campuran sayuran matang ke panci berisi ayam dan kaldu; didihkan perlahan 3 menit. Masukkan beras mentah sambil diaduk dan lanjutkan mendidihkan perlahan selama 15 menit.","Letakkan sisa sayuran cincang di atas nasi. Didihkan perlahan hingga nasi menyerap semua kaldu dan matang sepenuhnya (tambahkan air jika perlu).","Hiasi dan sajikan."],
["Nasi Jollof berasal dari Afrika Barat dan namanya berarti \"satu panci\".","Kaldu ayam buatan sendiri selalu yang terbaik—penuh rasa dan jauh lebih rendah natrium dibandingkan kaldu biasa atau natrium berkurang.","Gunakan sarung tangan sekali pakai saat mencincang cabai pedas. Buang biji dan selaput di dalamnya agar rasa pedasnya lebih ringan.","Cobalah mengganti ayam dengan daging sapi untuk variasi resep ini."],
["2 daging","1 sayuran, kalium sedang","2-1/2 makanan pokok bertepung"]),
R(2259,"Saus Cabai Manis Thailand",
"Rasakan cita rasa manis dan pedas masakan Thailand dengan versi rendah natrium Saus Cabai Manis Thailand dari ahli gizi DaVita, Erin.",
"8","2 sendok makan",
["3 siung bawang putih","2 cabai jalapeno merah","1/4 cangkir cuka putih suling","1/2 cangkir gula","14 sendok makan air","1/4 sendok teh garam","1 sendok makan tepung maizena"],
["Kupas siung bawang putih dan buang biji cabai.","Dalam blender, haluskan semua bahan, kecuali tepung maizena dan 2 sendok makan air.","Pindahkan campuran ke panci dan didihkan dengan api sedang-tinggi.","Kecilkan api ke sedang dan didihkan perlahan hingga campuran mengental, dan bawang putih serta cabai mulai melunak, sekitar 3 menit.","Campurkan tepung maizena dan 2 sendok makan air untuk membuat larutan.","Kocok campuran maizena dan terus didihkan perlahan satu menit lagi.","Biarkan dingin sepenuhnya sebelum disimpan dalam toples kaca di lemari es."],
["Sebagian besar saus botolan yang sebanding mengandung 400 mg natrium per porsi 2 sendok makan.","Gunakan cabai Serrano atau jenis cabai lain pilihan Anda. Lewati pembuangan biji untuk rasa lebih pedas.","Tepung maizena akan membantu saus sedikit mengental, sehingga potongan bawang putih-cabai tersuspensi dengan baik; jika tidak, Anda akan mendapatkan saus encer dengan potongan kecil mengapung di permukaan."],
["1/2 berkalori tinggi"]),
R(2260,"Slush Stroberi-Limun",
"Tepat menjelang musim panas: nikmati resep ramah ginjal Slush Stroberi-Limun hari ini.",
"1","1 cangkir",
["1/3 cangkir air lemon segar","1/2 cangkir stroberi, segar atau beku tanpa pemanis","1 sendok makan gula atau pemanis pilihan","1/2 cangkir es batu"],
["Dalam blender campurkan stroberi, air lemon, dan 1 sendok makan gula atau Splenda®. Blender hingga halus.","Dengan blender menyala, tambahkan 1/2 cangkir es batu, satu per satu, melalui lubang di tutup hingga minuman menjadi slush.","Seruput perlahan untuk menikmatinya."],
["Jika diinginkan, tambahkan 1/3 cangkir dasar limun atau dasar lemon bebas gula dari resep DaVita sebagai pengganti air lemon segar. Versi rendah gula yang dibuat dengan dasar limun bebas gula dan pemanis bebas gula memiliki 50 kalori dan 13 g karbohidrat. Hitung sebagai 1 buah kalium rendah dan satu pilihan karbohidrat."],
["1 buah, kalium sedang","1 berkalori tinggi"]),
R(2261,"Telur dan Paprika Italia",
"Resep Telur dan Paprika Italia yang mengenyangkan namun ramah ginjal ini adalah cara yang bagus untuk memulai hari Anda.",
"4","2/3 cangkir",
["1 cangkir paprika hijau","1/2 cangkir bawang bombai","1/4 cangkir basil segar","8 butir telur besar","1/4 sendok teh lada hitam","1/8 sendok teh serpihan cabai hancur (opsional)"],
["Cincang paprika, bawang bombai, dan basil.","Dalam wajan besar, masak dan tumis bawang bombai dan paprika hijau dalam minyak hingga empuk.","Kocok telur hingga tercampur; tambahkan lada hitam dan serpihan cabai hancur. Tuang ke wajan berisi bawang bombai dan paprika hijau.","Masak dengan api sedang. Saat campuran mulai mengeras di dasar dan sisi, angkat perlahan bagian yang matang dengan spatula agar telur mentah dapat mengalir ke dasar. Hindari terus-menerus mengaduk.","Masak hingga telur mengental merata tetapi masih lembap, 3 hingga 5 menit. Sajikan panas dengan basil segar di atasnya."],
["Ganti dengan 2 cangkir pengganti telur cair rendah kolesterol sebagai pengganti telur jika Anda menjalani diet rendah kolesterol."],
["2 daging","1 sayuran, kalium rendah","1 lemak"]),
R(2263,"Omelet Cetakan Wafel",
"Omelet Cetakan Wafel adalah penggunaan mengejutkan untuk cetakan wafel Anda. Sajikan dengan topping favorit Anda seperti salsa atau campurkan dengan sayuran favorit Anda.",
"1","1 wafel telur",
["1 sendok teh bawang bombai","1 sendok teh paprika hijau","2 butir telur besar","1 sendok teh mentega","1/8 sendok teh lada hitam"],
["Colokkan cetakan wafel untuk memanaskan.","Cincang halus bawang bombai dan paprika. Lelehkan mentega.","Dalam mangkuk, kocok ringan 2 telur. Tambahkan sayuran cincang halus, mentega leleh, dan lada hitam.","Semprot cetakan wafel dengan semprotan masak. Tuang seluruh isinya ke cetakan wafel.","Masak selama 2 menit, atau ikuti petunjuk cetakan wafel jika cetakan wafel Anda memiliki lampu indikator “siap”."],
["Penting untuk tidak mengocok terlalu banyak udara ke dalam telur."],
["2 daging","1 lemak"]),
R(2264,"Dip Sayur Kebun",
"Ahli gizi DaVita, Kim dari Missouri, membantu pasien dialisisnya makan dengan baik dan tetap sehat dengan antusiasme tinggi dan resep yang menggugah selera. Inilah kesempatan Anda mencoba salah satu resep tersebut, Dip Sayur Kebun yang ramah ginjal dan lezat.",
"20","2 sendok makan dip dengan masing-masing 2 potong sayuran",
["8 ons krim keju","1/4 cangkir lobak","1/4 cangkir bawang daun","1/4 cangkir mentimun","1/4 cangkir paprika hijau","4 wortel sedang","7 batang seledri","2 mentimun sedang","3 paprika merah sedang","3 paprika hijau sedang","1 cangkir krim asam","1 sendok makan gula","1/4 sendok teh garam","1/2 sendok teh campuran bumbu herba Mrs. Dash®"],
["Keluarkan krim keju agar melunak.","Cincang halus lobak, bawang daun, paprika hijau, dan 1/4 cangkir mentimun. Tiriskan mentimun.","Potong wortel dan seledri menjadi batang. Iris paprika dan 2 mentimun yang tersisa. Tata sayuran di nampan saji.","Dalam mangkuk pencampur besar, masukkan krim keju, krim asam, lobak, bawang daun, 1/4 cangkir mentimun cincang, 1/4 cangkir paprika hijau cincang, gula, garam, dan Mrs. Dash. Campur dengan mixer listrik pada kecepatan rendah sekitar 1 menit hingga tercampur rata.","Sendokkan ke dalam mangkuk saji."],
["Sajikan dip dengan biskuit rendah natrium sebagai pengganti sayuran jika diinginkan.","Sediakan 2 potong masing-masing sayuran per porsi."],
["1 sayuran, kalium sedang","1 lemak"]),
]
save(5,recs)
